# Launcher de Rayner para Creative Destruction.
# Abre una ventana con boton JUGAR. Por dentro: comprueba que el servidor este encendido, hace que el juego apunte a el
# (archivo hosts, se restaura al cerrar) y pasa las conexiones del juego al servidor de Rayner.
import socket, threading, time, os, sys, json, atexit, argparse, subprocess, secrets, webbrowser, shutil
import math, base64, struct, ctypes, traceback, zlib, array, datetime, random   # (los usa el servidor interno: asi el .exe los incluye)
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
if sys.stdout is None: sys.stdout = open(os.devnull, 'w')   # pythonw (sin consola)
if sys.stderr is None: sys.stderr = open(os.devnull, 'w')

VERSION = '3.7'
EDICION = 'anfitrion'   # 'anfitrion' = el de Rayner (con servidor); 'amigo' = solo para entrar
SERVIDOR_POR_DEFECTO = '81.57.59.179'
TCP = {80: 12080, 4002: 12002, 4006: 12006, 4010: 12010, 4021: 12021}
UDP = {4020: 12020}
DOMINIO = 'cd.tayarran.com'
MARCA = '# launcher-cd'
HOSTS = os.path.join(os.environ.get('SystemRoot', r'C:\Windows'), r'System32\drivers\etc\hosts')
CFG_DIR = os.path.join(os.environ.get('APPDATA', os.path.expanduser('~')), 'CDServerLauncher')
CFG = os.path.join(CFG_DIR, 'ajustes.json')
LOGF = os.path.join(CFG_DIR, 'launcher_log.txt')

# ---- modo servidor interno: el propio .exe arranca el servidor (no hace falta tener Python) ----
SALIDA_SRV = os.path.join(CFG_DIR, 'servidor_salida.txt')
if '--run-server' in sys.argv:
    _i = sys.argv.index('--run-server'); _resto = sys.argv[_i + 1:]; _src = None
    if '--srv-src' in _resto:
        _j = _resto.index('--srv-src'); _src = _resto[_j + 1]; _resto = _resto[:_j] + _resto[_j + 2:]
    if not _src: _src = os.path.join(getattr(sys, '_MEIPASS', os.path.dirname(os.path.abspath(__file__))), 'servidor_cd106_2022.py')
    os.makedirs(CFG_DIR, exist_ok=True)
    sys.stdout = sys.stderr = open(SALIDA_SRV, 'w', buffering=1, encoding='utf8')
    _fake = os.path.join(CFG_DIR, 'servidor.py'); sys.argv = [_fake] + _resto
    exec(compile(open(_src, encoding='utf8').read(), _src, 'exec'), {'__name__': '__main__', '__file__': _fake})
    sys.exit(0)

ap = argparse.ArgumentParser()
ap.add_argument('--servidor'); ap.add_argument('--sin-hosts', action='store_true'); ap.add_argument('--sin-ventana', action='store_true')
ap.add_argument('--puerto-ui', type=int, default=0); ap.add_argument('--srv-interno')
args = ap.parse_args()

def log(*a):
    try:
        os.makedirs(CFG_DIR, exist_ok=True)
        with open(LOGF, 'a', encoding='utf8') as f: f.write('[%s] %s\n' % (time.strftime('%H:%M:%S'), ' '.join(str(x) for x in a)))
    except Exception: pass

# ---------------- ajustes ----------------
def carga_ajustes():
    try: d = json.load(open(CFG, encoding='utf8'))
    except Exception: d = {}
    if args.servidor: d['servidor'] = args.servidor
    d.setdefault('servidor', SERVIDOR_POR_DEFECTO); d.setdefault('srv_py', ''); d.setdefault('guia_vista', False)
    if EDICION == 'amigo': d['modo'] = 'amigo'
    if not d.get('juego_dir') or not es_juego(d['juego_dir']): d['juego_dir'] = busca_juego()
    return d
def guarda_ajustes(d):
    try:
        os.makedirs(CFG_DIR, exist_ok=True); json.dump(d, open(CFG, 'w', encoding='utf8'), indent=1)
    except Exception as e: log('no pude guardar ajustes', e)
def es_juego(p):
    return bool(p) and os.path.isfile(os.path.join(p, 'client.exe'))
def busca_juego():
    c = []
    try:
        _d = os.path.dirname(os.path.abspath(__file__))
        c += [os.path.join(_d, '..', '..', 'CD-2022'), os.path.join(_d, '..', 'CD-2022'), os.path.join(_d, 'CD-2022')]
    except Exception: pass
    for env in ('ProgramFiles', 'ProgramFiles(x86)', 'LOCALAPPDATA'):
        b = os.environ.get(env)
        if b: c += [os.path.join(b, 'Creative Destruction'), os.path.join(b, 'Programs', 'Creative Destruction')]
    for l in 'CDEFGHIJ':
        c += [l + r':\CD-2022', l + r':\Creative Destruction', l + r':\Games\Creative Destruction', l + r':\SteamLibrary\steamapps\common\Creative Destruction',
              l + r':\Program Files (x86)\Steam\steamapps\common\Creative Destruction']
    for p in c:
        if es_juego(p): return os.path.normpath(p)
    return ''
AJ = carga_ajustes()

# ---------------- red ----------------
def estado_servidor(t=3.0):
    t0 = time.time()
    try:
        s = socket.create_connection((AJ['servidor'], TCP[80]), timeout=t); s.close()
        return True, int((time.time() - t0) * 1000)
    except OSError: return False, 0

def es_admin():
    if sys.platform != 'win32': return True
    try:
        import ctypes; return bool(ctypes.windll.shell32.IsUserAnAdmin())
    except Exception: return False
def pide_admin():
    """si no somos administrador, se vuelve a abrir pidiendo el permiso (aparece el aviso azul de Windows)"""
    if sys.platform != 'win32' or args.sin_hosts or es_admin(): return False
    try:
        import ctypes
        if getattr(sys, 'frozen', False): exe, par = sys.executable, ' '.join('"%s"' % a for a in sys.argv[1:])
        else: exe, par = sys.executable, ' '.join('"%s"' % a for a in ([os.path.abspath(sys.argv[0])] + sys.argv[1:]))
        r = ctypes.windll.shell32.ShellExecuteW(None, 'runas', exe, par, os.path.dirname(os.path.abspath(sys.argv[0])), 1)
        return r > 32
    except Exception as e: log('no pude pedir admin', e); return False

def leer_hosts():
    try: return [l.rstrip('\r\n') for l in open(HOSTS, encoding='utf8', errors='replace') if l.strip()]
    except OSError: return []
def quitar_hosts():
    if args.sin_hosts: return
    try:
        lin = [l for l in leer_hosts() if MARCA not in l]
        open(HOSTS, 'w', encoding='utf8', newline='').write('\r\n'.join(lin) + '\r\n')
    except Exception as e: log('no pude restaurar hosts', e)
def poner_hosts():
    if args.sin_hosts: return None
    try:
        lin = [l for l in leer_hosts() if MARCA not in l] + ['127.0.0.1 %s %s' % (DOMINIO, MARCA)]
        open(HOSTS, 'w', encoding='utf8', newline='').write('\r\n'.join(lin) + '\r\n'); return None
    except Exception as e:
        log('hosts error', repr(e))
        if not es_admin(): return 'Falta permiso de administrador. Cierra el programa y ábrelo con clic derecho > Ejecutar como administrador.'
        return 'Windows no deja modificar el archivo hosts (%s). Puede ser el antivirus: permite el cambio o desactiva la protección del archivo hosts.' % e

class Puente:
    def __init__(self): self.socks = []; self.conns = set(); self.activo = False; self.lock = threading.Lock()
    def _bombea(self, a, b):
        try:
            while True:
                d = a.recv(65536)
                if not d: break
                b.sendall(d)
        except OSError: pass
        for s in (a, b):
            try: s.shutdown(socket.SHUT_RDWR)
            except OSError: pass
            try: s.close()
            except OSError: pass
            self.conns.discard(s)
    def _tcp_conn(self, c, remoto):
        try: u = socket.create_connection((AJ['servidor'], remoto), timeout=8); u.settimeout(None)
        except OSError as e: log('sin conexion al servidor, puerto', remoto, e); c.close(); return
        for s in (c, u):
            try: s.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
            except OSError: pass
            self.conns.add(s)
        threading.Thread(target=self._bombea, args=(c, u), daemon=True).start()
        threading.Thread(target=self._bombea, args=(u, c), daemon=True).start()
    def _escucha_tcp(self, local, remoto):
        s = socket.socket(); s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        s.bind(('127.0.0.1', local)); s.listen(20); s.settimeout(0.5); self.socks.append(s)
        def run():
            while self.activo:
                try: c, _ = s.accept()
                except socket.timeout: continue
                except OSError: return
                c.settimeout(None)
                threading.Thread(target=self._tcp_conn, args=(c, remoto), daemon=True).start()
        threading.Thread(target=run, daemon=True).start()
    def _escucha_udp(self, local, remoto):
        # v3.5: el UDP de la batalla viaja DENTRO de una conexion TCP al servidor (puerto de batalla TCP). Asi no depende de que el router deje pasar el UDP.
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.bind(('127.0.0.1', local)); s.settimeout(0.5); self.socks.append(s)
        ses = {}; lock = threading.Lock()
        puerto_tun = TCP[4021]
        def devuelve(addr, t):
            buf = b''
            while self.activo:
                try: t.settimeout(120.0); d = t.recv(65536)
                except OSError: break
                if not d: break
                buf += d
                while len(buf) >= 2:
                    n = struct.unpack_from('<H', buf, 0)[0]
                    if len(buf) < 2 + n: break
                    dg = buf[2:2 + n]; buf = buf[2 + n:]
                    try: s.sendto(dg, addr)
                    except OSError: pass
            with lock: ses.pop(addr, None)
            try: t.close()
            except OSError: pass
        def run():
            while self.activo:
                try: d, addr = s.recvfrom(65536)
                except socket.timeout: continue
                except OSError: return
                with lock:
                    e = ses.get(addr)
                    if e is None:
                        try:
                            t = socket.create_connection((AJ['servidor'], puerto_tun), 10)
                            t.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1); t.sendall(b'UDPT'); self.conns.add(t)
                        except OSError:
                            continue
                        e = ses[addr] = t; threading.Thread(target=devuelve, args=(addr, t), daemon=True).start()
                try: e.sendall(struct.pack('<H', len(d)) + d)
                except OSError:
                    with lock: ses.pop(addr, None)
        threading.Thread(target=run, daemon=True).start()
    def inicia(self):
        """devuelve None si todo bien, o un texto de error"""
        self.activo = True
        for l, r in TCP.items():
            try: self._escucha_tcp(l, r)
            except OSError as e:
                self.para(); return 'El puerto %d de este PC está ocupado. Si tienes tu servidor encendido en este mismo PC, ciérralo; si no, cierra el otro programa que lo usa.' % l
        for l, r in UDP.items():
            try: self._escucha_udp(l, r)
            except OSError as e:
                self.para(); return 'El puerto UDP %d de este PC está ocupado.' % l
        return None
    def para(self):
        self.activo = False
        for s in self.socks + list(self.conns):
            try: s.shutdown(socket.SHUT_RDWR)
            except OSError: pass
            try: s.close()
            except OSError: pass
        self.socks = []; self.conns = set(); time.sleep(0.7)   # deja que los hilos de escucha terminen

PUENTE = Puente()
E = {'msg': '', 'err': '', 'ult': 0.0, 'visto': False, 'proc': None, 'srv': None, 'arrancando': False, 'puente_on': False}
MARCA_SRV = '# registrador-cd'     # la linea que pone el servidor en hosts
NOCON = 0x08000000 if sys.platform == 'win32' else 0

# ---------------- modo anfitrion: el launcher enciende el servidor ----------------
def servidor_interno():
    """ruta del servidor que va DENTRO del .exe (o el que se pasa con --srv-interno en pruebas); '' si no hay"""
    if args.srv_interno and os.path.isfile(args.srv_interno): return args.srv_interno
    if getattr(sys, 'frozen', False):
        p = os.path.join(getattr(sys, '_MEIPASS', ''), 'servidor_cd106_2022.py')
        return p if os.path.isfile(p) else ''
    p = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'servidor_cd106_2022.py')   # modo sin .exe: el servidor va junto al launcher
    return p if os.path.isfile(p) else ''
def busca_servidor_py():
    """servidor externo (solo cuando se usa el .py suelto): el mas reciente o el elegido a mano"""
    man = (AJ.get('srv_py') or '').strip().strip('"')
    if man and os.path.isfile(man): return man
    home = os.path.expanduser('~')
    carp = [os.path.dirname(sys.executable) if getattr(sys, 'frozen', False) else os.path.dirname(os.path.abspath(__file__)), CFG_DIR,
            os.path.join(home, 'Downloads'), os.path.join(home, 'Desktop'), os.path.join(home, 'Documents'), home, os.getcwd()]
    import glob
    cand = []
    for c in carp:
        cand += glob.glob(os.path.join(c, 'servidor_cd*.py'))
    cand = [p for p in set(cand) if os.path.isfile(p)]
    return max(cand, key=os.path.getmtime) if cand else ''
def busca_python():
    """un python.exe real (no el atajo de la Microsoft Store). Devuelve lista de comando o None"""
    for n in ('python', 'python3', 'py'):
        p = shutil.which(n)
        if p and 'WindowsApps' not in p: return [p, '-3'] if n == 'py' else [p]
    import glob
    loc = os.environ.get('LOCALAPPDATA', '')
    for pat in (os.path.join(loc, 'Programs', 'Python', 'Python3*', 'python.exe'), r'C:\Python3*\python.exe', r'C:\Program Files\Python3*\python.exe'):
        r = sorted(glob.glob(pat))
        if r: return [r[-1]]
    return None
def comando_servidor(extra):
    """(lista de comando, carpeta de datos, error). Interno = el .exe se llama a si mismo con --run-server"""
    ext = ['--sin-hosts'] if args.sin_hosts else []
    interno = servidor_interno()
    if interno:
        if getattr(sys, 'frozen', False): return [sys.executable, '--run-server'] + ext, CFG_DIR, None
        return [sys.executable, os.path.abspath(__file__), '--run-server', '--srv-src', interno] + ext, CFG_DIR, None
    py = busca_servidor_py(); cmd = busca_python()
    if not py: return None, None, 'No encuentro el servidor (servidor_cd106_2022.py). Ponlo en Descargas o elígelo en Ajustes.'
    if not cmd: return None, None, 'No encuentro Python en este PC. Instálalo desde python.org (marca "Add python.exe to PATH") y vuelve a intentarlo.'
    return cmd + ['-u', py] + ext, os.path.dirname(py), None
def datos_dir():
    if servidor_interno(): return CFG_DIR
    py = busca_servidor_py(); return os.path.dirname(py) if py else CFG_DIR
def servidor_disponible():
    return bool(servidor_interno() or (busca_servidor_py() and busca_python()))
def migra_estado():
    """si ya tenias tu cuenta guardada junto al servidor antiguo (Descargas...), se copia a la carpeta del launcher la primera vez"""
    destino = os.path.join(CFG_DIR, 'estado_jugador.json')
    if os.path.isfile(destino) or not servidor_interno(): return
    home = os.path.expanduser('~'); py = busca_servidor_py()
    for c in ([os.path.dirname(py)] if py else []) + [os.path.join(home, 'Downloads'), os.path.join(home, 'Desktop'), os.path.join(home, 'Documents'), home]:
        o = os.path.join(c, 'estado_jugador.json')
        if os.path.isfile(o):
            try: os.makedirs(CFG_DIR, exist_ok=True); shutil.copy2(o, destino); log('cuenta migrada desde', o)
            except Exception as e: log('no pude migrar la cuenta', e)
            return
def srv_corre(): return E['srv'] is not None and E['srv'].poll() is None
def puerto_abierto(p, t=0.6):
    try: socket.create_connection(('127.0.0.1', p), timeout=t).close(); return True
    except OSError: return False
def cola(path, n=8000):
    try:
        with open(path, 'rb') as f:
            f.seek(0, 2); tam = f.tell(); f.seek(max(0, tam - n)); return f.read().decode('utf8', 'replace')
    except OSError: return ''
def version_servidor():
    import re
    m = re.findall(r'=== VERSION (v\d+)', cola(SALIDA_SRV, 20000))
    return m[-1] if m else ''
def limpia_hosts_srv():
    if args.sin_hosts: return
    try:
        lin = [l for l in leer_hosts() if MARCA_SRV not in l and MARCA not in l]
        open(HOSTS, 'w', encoding='utf8', newline='').write('\r\n'.join(lin) + '\r\n')
        if sys.platform == 'win32': subprocess.run(['ipconfig', '/flushdns'], capture_output=True, creationflags=NOCON)
    except Exception as e: log('no pude limpiar hosts', e)
def enciende_servidor():
    """None si ok, o texto de error"""
    if srv_corre(): return None
    cmd, carpeta, err = comando_servidor([])
    if err: return err
    if puerto_abierto(80) and not srv_corre():
        return 'El puerto 80 ya está en uso (¿tienes otro servidor abierto en PowerShell?). Ciérralo y vuelve a pulsar.'
    os.makedirs(CFG_DIR, exist_ok=True); migra_estado()
    try: open(SALIDA_SRV, 'w').close()
    except OSError: pass
    try:
        E['srv'] = subprocess.Popen(cmd, cwd=carpeta, stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                                    creationflags=NOCON, env=dict(os.environ, PYTHONIOENCODING='utf8'))
    except Exception as e: return 'No pude encender el servidor: %s' % e
    t0 = time.time()
    while time.time() - t0 < 60:
        if E['srv'].poll() is not None:
            t = cola(SALIDA_SRV, 1500).strip().splitlines()
            E['srv'] = None; limpia_hosts_srv()
            return 'El servidor se cerró al arrancar: ' + (t[-1][:200] if t else 'sin mensaje') + ' (mira la pestaña Registro)'
        if puerto_abierto(80) and 'Servidor listo' in cola(SALIDA_SRV, 20000): log('servidor encendido', version_servidor()); return None
        time.sleep(0.4)
    apaga_servidor(); return 'El servidor tardó demasiado en encenderse (mira la pestaña Registro).'
def apaga_servidor():
    p = E['srv']; E['srv'] = None
    if p is not None and p.poll() is None:
        try:
            if sys.platform == 'win32': subprocess.run(['taskkill', '/F', '/T', '/PID', str(p.pid)], capture_output=True, creationflags=NOCON)   # el .exe se parte en 2 procesos: se matan los dos
            else: p.terminate()
            p.wait(5)
        except Exception:
            try: p.kill()
            except Exception: pass
    limpia_hosts_srv()

def abre_juego():
    if es_juego(AJ.get('juego_dir')) is False: return 'No encuentro el juego. Abre Ajustes y elige la carpeta donde está client.exe.'
    try: E['proc'] = subprocess.Popen([os.path.join(AJ['juego_dir'], 'client.exe')], cwd=AJ['juego_dir'])
    except Exception as ex: return 'No pude abrir el juego: %s' % ex
    return None
def juego_abierto(): return E['proc'] is not None and E['proc'].poll() is None
def activo(): return srv_corre() if AJ['modo'] == 'anfitrion' else E['puente_on']

def accion_jugar():
    if E['arrancando']: return
    E['err'] = ''
    if not es_juego(AJ.get('juego_dir')):
        E['err'] = 'No encuentro el juego. Abre Ajustes y elige la carpeta donde está client.exe.'; return
    E['arrancando'] = True
    try:
        if AJ['modo'] == 'anfitrion':
            e = enciende_servidor()
            if e: E['err'] = e; return
        elif not E['puente_on']:
            ok, _ = estado_servidor()
            if not ok: E['err'] = 'El servidor está apagado ahora mismo. Vuelve a intentarlo cuando lo encienda su dueño.'; return
            e = poner_hosts()
            if e: E['err'] = e; return
            e = PUENTE.inicia()
            if e: quitar_hosts(); E['err'] = e; return
            E['puente_on'] = True
        if not juego_abierto():
            e = abre_juego()
            if e: E['err'] = e; return
        log('jugando', AJ['modo'])
    finally: E['arrancando'] = False
def accion_servidor():
    """boton SERVIDOR (solo anfitrion): enciende o apaga el servidor sin abrir el juego"""
    if E['arrancando'] or EDICION != 'anfitrion': return
    if srv_corre(): apaga_servidor(); E['err'] = ''; return
    E['arrancando'] = True
    try:
        e = enciende_servidor(); E['err'] = e or ''
    finally: E['arrancando'] = False
def accion_detener():
    if AJ['modo'] == 'anfitrion': apaga_servidor()
    else: PUENTE.para(); quitar_hosts(); E['puente_on'] = False
    E['err'] = ''; log('detenido')
# ---- v3.6: actualizacion automatica desde GitHub (repositorio publico de Rayner) ----
REPO_RAW = 'https://raw.githubusercontent.com/Mundogh/cd-launcher/main/'
def _vt(v):
    import re
    return tuple(int(x) for x in re.findall(r'\d+', str(v)))
def comprueba_actualizacion():
    """lee version.json del repositorio; si hay una version mas nueva para esta edicion lo deja en E['upd']"""
    try:
        if getattr(sys, 'frozen', False): return
        import urllib.request
        rq = urllib.request.Request(REPO_RAW + 'version.json?t=%d' % int(time.time()), headers={'User-Agent': 'cd-launcher', 'Cache-Control': 'no-cache'})
        d = json.loads(urllib.request.urlopen(rq, timeout=6).read().decode('utf8'))
        a = d.get(EDICION)
        if a and _vt(d.get('version', '0')) > _vt(VERSION):
            E['upd'] = {'version': str(d['version']), 'archivo': a['archivo'], 'sha256': a['sha256'], 'notas': d.get('notas', '')}
            log('actualizacion disponible: %s -> %s' % (VERSION, d['version']))
        else: E['upd'] = None
    except Exception as e: log('no pude comprobar actualizaciones: %s' % e)
def aplica_actualizacion():
    u = E.get('upd')
    if not u or E.get('upd_busy'): return
    E['upd_busy'] = True; E['err'] = ''
    try:
        import urllib.request, hashlib
        data = urllib.request.urlopen(urllib.request.Request(REPO_RAW + u['archivo'] + '?t=%d' % int(time.time()), headers={'User-Agent': 'cd-launcher'}), timeout=60).read()
        if hashlib.sha256(data).hexdigest().lower() != u['sha256'].lower(): raise Exception('el archivo descargado no coincide (no se ha cambiado nada)')
        compile(data.decode('utf8'), 'nuevo', 'exec')
        me = os.path.abspath(__file__)
        shutil.copy2(me, me + '.bak')
        with open(me + '.nuevo', 'wb') as f: f.write(data)
        os.replace(me + '.nuevo', me)
        log('actualizado a %s; reiniciando' % u['version'])
        exe = sys.executable
        _w = os.path.join(os.path.dirname(exe), 'pythonw.exe')
        if os.path.isfile(_w): exe = _w   # sin ventana de consola
        cmd = 'ping -n 4 127.0.0.1 >nul & start "" "%s" "%s"' % (exe, me)
        subprocess.Popen(['cmd', '/c', cmd], creationflags=0x08000000, close_fds=True)
        SALIR.set()
    except Exception as e:
        log('error al actualizar: %s' % e); E['err'] = 'No pude actualizar: %s' % e
