def limpieza():
    try: PUENTE.para()
    except Exception: pass
    try: apaga_servidor()
    except Exception: pass
    quitar_hosts()
atexit.register(limpieza)

def elige_carpeta():
    try:
        r = subprocess.run(['powershell', '-NoProfile', '-STA', '-Command',
            "Add-Type -AssemblyName System.Windows.Forms; $f=New-Object System.Windows.Forms.FolderBrowserDialog; $f.Description='Elige la carpeta del juego (donde esta client.exe)'; if($f.ShowDialog() -eq 'OK'){Write-Output $f.SelectedPath}"],
            capture_output=True, text=True, timeout=300, creationflags=NOCON)
        return r.stdout.strip()
    except Exception as e: log('carpeta', e); return ''
def elige_archivo():
    try:
        r = subprocess.run(['powershell', '-NoProfile', '-STA', '-Command',
            "Add-Type -AssemblyName System.Windows.Forms; $f=New-Object System.Windows.Forms.OpenFileDialog; $f.Filter='Servidor (*.py)|*.py'; $f.Title='Elige el archivo del servidor'; if($f.ShowDialog() -eq 'OK'){Write-Output $f.FileName}"],
            capture_output=True, text=True, timeout=300, creationflags=NOCON)
        return r.stdout.strip()
    except Exception as e: log('archivo', e); return ''

